/** One order by name, or throw: a typo in a test must fail loudly. */
export function order(name) {
  const o = OCT_ORDERS.find((x) => x.name === name);
  if (!o) throw new Error(`no fixture order ${name}`);
  return o;
}

/** The shipments one order's AWBs point at. */
export function shipmentsFor(name) {
  const awbs = order(name).awbs;
  return OCT_SHIPMENTS.filter((s) => awbs.includes(s.awb));
}
